import fs from 'fs';
import path from 'path';

const TRANSLATIONS_DIR = path.join(process.cwd(), 'public/locales');

interface PageContent {
  es: Record<string, unknown>;
  en: Record<string, unknown>;
}

interface SectionContent {
  firstH3?: string;
  secondH3?: string;
  [key: string]: unknown;
}

interface FullPageContent {
  section1?: SectionContent;
  section2?: SectionContent;
  section3?: SectionContent;
  section4?: SectionContent;
  section5?: SectionContent;
  section6?: SectionContent;
  [key: string]: unknown;
}

function flattenContent(content: FullPageContent, prefix = ''): Record<string, string> {
  const result: Record<string, string> = {};

  for (const [key, value] of Object.entries(content)) {
    const newPrefix = prefix ? `${prefix}.${key}` : key;

    if (typeof value === 'string') {
      result[newPrefix] = value;
    } else if (typeof value === 'object' && value !== null) {
      const flattened = flattenContent(value as FullPageContent, newPrefix);
      Object.assign(result, flattened);
    }
  }

  return result;
}

export async function savePageTranslationsToJson(
  slug: string,
  content: PageContent
): Promise<void> {
  for (const lang of ['es', 'en'] as const) {
    const langDir = path.join(TRANSLATIONS_DIR, lang);
    const filePath = path.join(langDir, 'pages.json');

    // Cargar archivo existente o crear nuevo
    let existingTranslations: Record<string, string> = {};
    if (fs.existsSync(filePath)) {
      try {
        existingTranslations = JSON.parse(fs.readFileSync(filePath, 'utf-8'));
      } catch (e) {
        existingTranslations = {};
      }
    }

    // Aplanar contenido y guardar con prefijo pages.{slug}
    if (content[lang]) {
      const flattened = flattenContent(content[lang] as FullPageContent, `pages.${slug}`);

      // Eliminar entradas anteriores del mismo slug
      for (const key of Object.keys(existingTranslations)) {
        if (key.startsWith(`pages.${slug}.`)) {
          delete existingTranslations[key];
        }
      }

      // Agregar nuevas entradas
      Object.assign(existingTranslations, flattened);
    }

    // Escribir archivo
    fs.writeFileSync(filePath, JSON.stringify(existingTranslations, null, 2));
  }

  console.log(`[i18n] Guardadas traducciones para página: ${slug}`);
}

export async function deletePageTranslationsFromJson(slug: string): Promise<void> {
  for (const lang of ['es', 'en'] as const) {
    const filePath = path.join(TRANSLATIONS_DIR, lang, 'pages.json');

    if (fs.existsSync(filePath)) {
      const translations = JSON.parse(fs.readFileSync(filePath, 'utf-8'));

      // Eliminar claves de la página
      for (const key of Object.keys(translations)) {
        if (key.startsWith(`pages.${slug}.`)) {
          delete translations[key];
        }
      }

      fs.writeFileSync(filePath, JSON.stringify(translations, null, 2));
    }
  }
}
